from typing import Concatenate, Callable, ParamSpec
P = ParamSpec('P')
def with_logging(f: Callable[P, str]) -> Callable[Concatenate[str, P], str]:
    def wrapper(prefix: str, *args: P.args, **kwargs: P.kwargs) -> str:
        return prefix + f(*args, **kwargs)
    return wrapper
@with_logging
def greet(name: str) -> str:
    return f'Hello {name}'
print(greet('DEBUG: ', 'World'))

